using Godot;
using System;
using System.Collections.Generic;
using GArray=Godot.Collections.Array;
using Settings=Godot.Collections.Dictionary;
public partial class PowderSolverOperations
{
    private static GDScript Adapter()=>GD.Load<GDScript>("res://scripts/actors/physics/powder/powder_solver.gd");
    private static void Reaction(Frame f,Variant callback,int i,Settings hit,Vector3 correction,double h){if(h<=0)return;var contact=hit.Duplicate();var batch=f.Batches[f.Owners[i]];contact["grain_mass"]=f.Masses[i];contact["grain_key"]=batch.Row["id"].AsString()+":"+f.Slots[i];contact["grain_velocity"]=f.Velocities[i]*Get(hit,"source_speed",1).AsSingle();Adapter().Call("_invoke_reaction",callback,contact,-correction*(float)(f.Masses[i]/h),-correction*f.Masses[i]);}
    private static void Boundary(Frame f,int i,Settings hit,double h,Variant reaction,bool countContact){var batch=f.Batches[f.Owners[i]];var settings=batch.Settings;var normal=hit["normal"].AsVector3();double depth=f.Radii[i]-normal.Dot(f.Positions[i]-hit["point"].AsVector3());var correction=normal*(float)Math.Max(0,depth);f.Positions[i]+=correction;var relative=f.Positions[i]-f.Previous[i]-Get(hit,"velocity",Vector3.Zero).AsVector3()*(float)h;var tangent=relative-normal*relative.Dot(normal);double length=tangent.Length(),support=Math.Max(depth,(-batch.Row["gravity"].AsVector3()).Dot(normal)*h*h),muStatic=Math.Sqrt(settings["static_friction"].AsDouble()*Get(hit,"friction",settings["static_friction"]).AsDouble()),muDynamic=Math.Sqrt(settings["dynamic_friction"].AsDouble()*Get(hit,"friction",settings["dynamic_friction"]).AsDouble());if(length>1e-9&&countContact){double fraction=length<muStatic*support?1:Math.Min(1,(muDynamic+settings["rolling"].AsDouble())*support/length);f.Positions[i]-=tangent*(float)fraction;correction-=tangent*(float)fraction;}if(countContact){f.Contacts[i]++;int id=batch.Ids[f.Slots[i]];var supports=batch.State["powder_supports"].AsGodotDictionary();var old=supports.TryGetValue(id,out var value)?value.AsGodotDictionary():new Settings();var gravity=-batch.Row["gravity"].AsVector3();if(old.Count==0||normal.Dot(gravity)>=old["normal"].AsVector3().Dot(gravity))supports[id]=hit;}if(!correction.IsZeroApprox())Reaction(f,reaction,i,hit,correction,h);}
    private static Settings Collide(Variant callback,Batch batch,Vector3 from,Vector3 to,float radius,double h)=>Adapter().Call("_invoke_collision",callback,batch.Row["id"],from,to,radius,h).AsGodotDictionary();
    public void solve(RefCounted owner,GArray input,Variant collide,Variant reaction,Variant prepare)
    {
        ulong started=Godot.Time.GetTicksUsec();owner.Set("batches",input);owner.Set("checks",0);owner.Set("error","");foreach(string key in new[]{"positions","velocities"})owner.Set(key,Array.Empty<Vector3>());foreach(string key in new[]{"radii","masses","inverse_masses"})owner.Set(key,Array.Empty<float>());foreach(string key in new[]{"owners","slots"})owner.Set(key,Array.Empty<int>());var f=new Frame(owner);try
        {
            int substeps=1,iterations=2;double maximumRadius=.001,minimumRadius=double.PositiveInfinity,maximumH=0,maximumSpeed=0;var positions=new List<Vector3>();var velocities=new List<Vector3>();var radii=new List<float>();var masses=new List<float>();var inverse=new List<float>();var owners=new List<int>();var slots=new List<int>();for(int b=0;b<f.Batches.Length;b++){var batch=f.Batches[b];var settings=batch.Settings;batch.State["powder_supports"]=new Settings();substeps=Math.Max(substeps,settings["substeps"].AsInt32());iterations=Math.Max(iterations,settings["iterations"].AsInt32());maximumH=Math.Max(maximumH,batch.Row["h"].AsDouble());var grainRadii=batch.State["powder_radii"].AsFloat32Array();for(int i=0;i<batch.Points.Length;i++){double radius=Math.Max(.0001,grainRadii[i]),mass=settings["density"].AsDouble()*4/3*Math.PI*Math.Pow(radius,3);batch.Masses[i]=(float)mass;positions.Add(batch.Points[i]);velocities.Add(batch.Velocities[i]);radii.Add((float)radius);masses.Add((float)mass);bool deposited=batch.Phase.Length>0&&batch.Phase[i]==1;inverse.Add(batch.Row["moving"].AsBool()&&!deposited?(float)(1/Math.Max(1e-9,mass)):0);owners.Add(b);slots.Add(i);maximumRadius=Math.Max(maximumRadius,radius);minimumRadius=Math.Min(minimumRadius,radius);maximumSpeed=Math.Max(maximumSpeed,batch.Velocities[i].Length());}}f.Positions=positions.ToArray();f.Velocities=velocities.ToArray();f.Radii=radii.ToArray();f.Masses=masses.ToArray();f.Inverse=inverse.ToArray();f.Owners=owners.ToArray();f.Slots=slots.ToArray();if(f.Positions.Length==0)return;substeps=Math.Clamp(Math.Max(substeps,(int)Math.Ceiling((maximumSpeed+20*maximumH)*maximumH/Math.Max(.001,minimumRadius*.6))),1,16);var boundaries=new GArray[f.Positions.Length];f.Contacts=new int[f.Positions.Length];
            for(int substep=0;substep<substeps;substep++)
            {
                Adapter().Call("_invoke_prepare",prepare,(double)(substep+1)/substeps);f.Previous=(Vector3[])f.Positions.Clone();Array.Clear(f.Contacts);for(int i=0;i<f.Positions.Length;i++){var batch=f.Batches[f.Owners[i]];var settings=batch.Settings;double h=batch.Row["h"].AsDouble()/substeps;boundaries[i]=new GArray();if(f.Inverse[i]==0||h<=0)continue;int index=f.Slots[i];var acceleration=batch.Row["gravity"].AsVector3()*settings["gravity_scale"].AsSingle()+batch.Row["force"].AsVector3()/f.Masses[i];if(substep==0)f.Velocities[i]+=batch.Row["impulse"].AsVector3()/f.Masses[i];var wind=batch.Row["wind"].AsVector3();long seed=batch.Ids[index];double time=batch.State["powder_time"].AsDouble();wind+=new Vector3((float)Math.Sin(time*1.7+seed*.73),(float)Math.Sin(time*1.31+seed*.37),(float)Math.Cos(time*1.83+seed*.51))*settings["turbulence"].AsSingle();var relative=wind-f.Velocities[i];double shelter=1/(1+Math.Max(0,batch.Contacts[index]-3)*.4),drag=.5*1.225*settings["air_drag"].AsDouble()*Math.PI*f.Radii[i]*f.Radii[i]/f.Masses[i]*relative.Length()*settings["wind_influence"].AsDouble()*shelter;f.Velocities[i]+=relative*(float)(1-Math.Exp(-drag*h));f.Velocities[i]=(f.Velocities[i]+acceleration*(float)h).LimitLength((float)Math.Min(settings["max_speed"].AsDouble(),f.Radii[i]*.65*substeps/Math.Max(.000001,batch.Row["h"].AsDouble())));if(batch.Sleep[index]>=settings["sleep_delay"].AsDouble()&&acceleration.Length()<20&&relative.Length()*drag<.1&&batch.Row["impulse"].AsVector3().IsZeroApprox())f.Velocities[i]=acceleration*(float)h;f.Positions[i]+=f.Velocities[i]*(float)h;if(batch.Config["collision"].AsBool()){var result=Collide(collide,batch,f.Previous[i],f.Positions[i],f.Radii[i],h);foreach(var hit in Get(result,"hits",new GArray()).AsGodotArray())boundaries[i].Add(hit);var correction=result["position"].AsVector3()-f.Positions[i];f.Positions[i]=result["position"].AsVector3();if(!correction.IsZeroApprox()&&boundaries[i].Count>0)Reaction(f,reaction,i,boundaries[i][0].AsGodotDictionary(),correction,h);}}
                var incomingVelocities=(Vector3[])f.Velocities.Clone();if(!Neighbors(f,maximumRadius))return;f.Lambdas=new float[f.Pairs.Length/2];for(int iteration=0;iteration<iterations;iteration++){for(int pair=0;pair<f.Pairs.Length/2;pair++)Contact(f,pair,iterations,substeps,iteration==iterations-1);for(int i=0;i<f.Positions.Length;i++){if(f.Inverse[i]==0)continue;var batch=f.Batches[f.Owners[i]];double h=batch.Row["h"].AsDouble()/substeps;foreach(var hit in boundaries[i])Boundary(f,i,hit.AsGodotDictionary(),h,reaction,iteration==iterations-1);}}
                for(int i=0;i<f.Positions.Length;i++){var batch=f.Batches[f.Owners[i]];var settings=batch.Settings;double h=batch.Row["h"].AsDouble()/substeps;if(f.Inverse[i]==0||h<=0)continue;if(batch.Config["collision"].AsBool()){var result=Collide(collide,batch,f.Previous[i],f.Positions[i],f.Radii[i],h);var correction=result["position"].AsVector3()-f.Positions[i];f.Positions[i]=result["position"].AsVector3();foreach(var value in Get(result,"hits",new GArray()).AsGodotArray()){var hit=value.AsGodotDictionary();if(boundaries[i].Count==0&&!correction.IsZeroApprox())Reaction(f,reaction,i,hit,correction,h);Boundary(f,i,hit,h,reaction,false);}}var incoming=f.Velocities[i];f.Velocities[i]=(f.Positions[i]-f.Previous[i])/(float)h;foreach(var value in boundaries[i]){var hit=value.AsGodotDictionary();var normal=hit["normal"].AsVector3();var surface=Get(hit,"velocity",Vector3.Zero).AsVector3();double impact=(incoming-surface).Dot(normal);if(impact<-.3){double bounce=Math.Sqrt(settings["restitution"].AsDouble()*Get(hit,"restitution",settings["restitution"]).AsDouble()),extra=Math.Max(0,-impact*bounce-(f.Velocities[i]-surface).Dot(normal));f.Velocities[i]+=normal*(float)extra;if(extra>0)Adapter().Call("_invoke_reaction",reaction,hit,-normal*(float)(extra*f.Masses[i]),Vector3.Zero);}}f.Velocities[i]*=(float)Math.Exp(-settings["damping"].AsDouble()*h);if(!f.Positions[i].IsFinite()||!f.Velocities[i].IsFinite()){f.Positions[i]=f.Previous[i];f.Velocities[i]=Vector3.Zero;f.Error="Non-finite granular state was recovered; reduce forces or source overlap.";}f.Velocities[i]=f.Velocities[i].LimitLength(settings["max_speed"].AsSingle());int index=f.Slots[i];if(f.Contacts[i]>0&&f.Velocities[i].Length()<settings["sleep_speed"].AsDouble()){batch.Sleep[index]+=(float)h;if(batch.Sleep[index]>=settings["sleep_delay"].AsDouble())f.Velocities[i]=Vector3.Zero;}else batch.Sleep[index]=0;batch.Contacts[index]=f.Contacts[i];batch.Compaction[index]=(float)Math.Max(batch.Compaction[index]*.999,Math.Clamp((double)f.Contacts[i]/12,0,1));}for(int pair=0;pair<f.Pairs.Length/2;pair++)VelocityContact(f,pair,incomingVelocities);
            }
            for(int i=0;i<f.Positions.Length;i++){var batch=f.Batches[f.Owners[i]];batch.Points[f.Slots[i]]=f.Positions[i];batch.Velocities[f.Slots[i]]=f.Velocities[i];}foreach(var batch in f.Batches){batch.State["points"]=batch.Points;batch.State["velocities"]=batch.Velocities;}Prune(f);owner.Set("elapsed_usec",Godot.Time.GetTicksUsec()-started);
        }
        finally{f.Commit();}
    }
    public bool neighbors(RefCounted owner,double radius){var frame=new Frame(owner);bool result=Neighbors(frame,radius);frame.Commit();return result;}
    public void contact(RefCounted owner,int pair,int iterations,int substeps,bool count){var frame=new Frame(owner);Contact(frame,pair,iterations,substeps,count);frame.Commit();}
    public void boundary(RefCounted owner,int i,Settings hit,double h,Variant reaction,bool count){var frame=new Frame(owner);Boundary(frame,i,hit,h,reaction,count);frame.Commit();}
    public void reaction(RefCounted owner,Variant callback,int i,Settings hit,Vector3 correction,double h){var frame=new Frame(owner);Reaction(frame,callback,i,hit,correction,h);frame.Commit();}
    public void velocity_contact(RefCounted owner,int pair,Vector3[] incoming){var frame=new Frame(owner);VelocityContact(frame,pair,incoming);frame.Commit();}
    public void prune_bonds(RefCounted owner){var frame=new Frame(owner);Prune(frame);frame.Commit();}
}
